insert into preguntas (tema_id, enunciado, alternativas, correcta, dificultad, activa, imagen_url, creada_por)
values
('38739805-0d32-4226-abaf-8caf023e9c24', 'En un juego de mesa se pueden obtener tarjetas de Diamante (suma 10 puntos), Estrella (suma 5 puntos) y Calavera (resta 20 puntos), como se muestra en la imagen. Al finalizar una partida, cuatro jugadores habían sacado las siguientes tarjetas: Claudio: 5 Diamante, 10 Estrella, 1 Calavera. María: 3 Diamante, 10 Estrella, 0 Calavera. Angélica: 5 Diamante, 5 Estrella, 2 Calavera. Roberto: 8 Diamante, 5 Estrella, 1 Calavera. ¿Cuál de los jugadores obtuvo el mayor puntaje en esta partida?', to_jsonb(ARRAY['Claudio','María','Angélica','Roberto']), 3, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId8.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una persona compra manzanas en cajas de 24 unidades para vender en su local. Si esta persona hace un pedido de 45 de estas cajas, pero le llegaron solo 38 cajas, ¿cuántas manzanas le faltaron en el pedido?', to_jsonb(ARRAY['42','148','168','278']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'José tiene 90 dulces y se quedará con 18, repartiendo el resto en partes iguales entre ocho amigos. ¿Cuántos dulces recibirá cada amigo de José?', to_jsonb(ARRAY['8','9','10','11']), 1, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Considera el siguiente modelo que permite estimar la estatura, en centímetros, que tendrán niñas y niños cuando terminen su desarrollo: [estatura del padre (cm) + estatura de la madre (cm) + 13 · P] / 2, tal que P = 1 si su sexo es masculino, y P = −1 si su sexo es femenino. ¿Cuál será la estatura estimada de un niño de sexo masculino cuando termine su desarrollo si su madre mide 159 cm y su padre mide 168 cm?', to_jsonb(ARRAY['157 cm','163,5 cm','170 cm','176,5 cm']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la figura adjunta se representa una barra de 20 kg con tres discos distintos en cada lado. Los discos de cada lado tienen una masa de 5 kg, 10 kg y 15 kg. Si se quiere levantar la misma cantidad de kilogramos usando solo discos de 10 kg, ¿cuántos discos se deben colocar a cada lado de la barra?', to_jsonb(ARRAY['3','4','5','6']), 0, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId11.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Sandra y Miguel quieren leer, cada uno por su cuenta, un libro de 175 páginas en 5 días. Sandra decide leer 40 páginas el primer día, y cada día en adelante leer 3 páginas menos que el día anterior, mientras que Miguel decide leer 25 páginas el primer día, y cada día en adelante leer 5 páginas más que el día anterior. Si ambos cumplen con la lectura diaria estipulada, ¿cuál de las siguientes afirmaciones es verdadera con respecto al plazo de lectura de Sandra y Miguel?', to_jsonb(ARRAY['Ambos alcanzaron a leer el libro en el plazo.','Sandra alcanzó a leer el libro en el plazo, pero Miguel no.','Miguel alcanzó a leer el libro en el plazo, pero Sandra no.','Ninguno alcanzó a leer el libro en el plazo.']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', '¿Cuál es el valor de 2 · (2√3) · √3?', to_jsonb(ARRAY['12','4√18','12√3','24']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Considera las siguientes botellas de agua, de 2⅛ L y 1¼ L de capacidad respectivamente, como se muestra en la imagen. ¿Cuál de las siguientes expresiones representa la diferencia de capacidad entre ambas botellas, en litros?', to_jsonb(ARRAY['(2 − 1) − 1/4 + 1/8','(2 − 1) + 1/4 − 1/8','(2 − 1) + 1/8 − 1/4','(2 + 1) − 1/8 + 1/4']), 2, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId12.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Para calcular el monto final de dinero que se tendrá por medio de un interés simple mensual del i %, después de una cantidad n de meses, se utiliza la siguiente expresión: Cf = Ci · (1 + i · n / 100), tal que Cf es el monto final de dinero y Ci es el monto inicial de dinero. Considera una inversión con un monto inicial de $100 000 al que se le aplica un interés simple mensual del 20 %. ¿Cuánto dinero se tendrá transcurridos 5 meses?', to_jsonb(ARRAY['$102 000','$110 000','$120 000','$200 000']), 3, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En el siguiente mapa se presenta la hora en cuatro ciudades del mundo en un mismo momento del día lunes. Una persona viaja en un vuelo directo desde Nueva York hasta Tokio. Su vuelo partió a las 05:00 horas de Nueva York de ese día lunes y duró 14,5 horas. ¿A qué hora de Tokio aterrizó el vuelo de esta persona?', to_jsonb(ARRAY['A las 19:50 del día lunes','A las 19:30 del día lunes','A las 09:30 del día martes','A las 09:50 del día miércoles']), 2, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId13.jpeg', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la entrada de una obra de teatro, hay una persona encargada de recibir los tickets de entrada de los asistentes. Si se estima que la persona encargada recibe 15 tickets cada 60 segundos, ¿cuál de las siguientes expresiones permite estimar la cantidad de tickets que recibe cada t minutos?', to_jsonb(ARRAY['15t','900t','4t','t/4']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', '¿Qué número corresponde al 15 % de 480?', to_jsonb(ARRAY['28,8','31,3','68','72']), 3, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En una prueba, el índice de dificultad de una pregunta se calcula como c/n, tal que c es la cantidad de personas que respondieron correctamente la pregunta y n es el total de personas que la respondieron. Considera una pregunta que fue respondida correctamente por 280 personas e incorrectamente por 560 personas. ¿Cuál es el índice de dificultad de esa pregunta?', to_jsonb(ARRAY['1/3','1/2','2/3','2']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una empresa de estacionamientos cobra una tarifa de $25 por cada minuto de uso. Por un incremento en los costos, la empresa decide aumentar la tarifa por minuto en un 12 %. ¿Cuánto se tiene que pagar por usar el estacionamiento 10 minutos, después del aumento de la tarifa?', to_jsonb(ARRAY['$370','$300','$280','$120']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Para arrendar botes en una empresa se debe enviar una solicitud. En la figura adjunta se representa el flujo de estados de una solicitud: Enviada → Aprobada → En curso → Finalizada → Pagada. Se presenta una tabla con el estado de las últimas 20 solicitudes. ¿Cuál es el porcentaje de las solicitudes que está o ya ha pasado por el estado "Aprobada"?', to_jsonb(ARRAY['13 %','15 %','65 %','75 %']), 3, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId18.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la siguiente tabla se presenta la cantidad de licencias de conducir tramitadas a mujeres durante el 2021 por clase: A1: 244, A2: 3617, A3: 1962, A4: 1535, A5: 199, B: 248 700, C: 5859, D: 3734, E: 7, F: 687 (Total: 266 544). ¿Cuál de las siguientes expresiones representa el porcentaje de licencias clase A1 que se tramitaron, con respecto al total de licencias cuya clase comienza con la letra A?', to_jsonb(ARRAY['(244 / 7557) · 100 %','(244 / 7313) · 100 %','(244 / 266 544) · 100 %','(7557 / 244) · 100 %']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'La Maratón de Santiago, realizada el 28 de abril de 2024 tenía tres categorías 10k, 21k y 42k, y participaron 31 000 corredores. Del total de corredores, un 25 % eran extranjeros y un 12 % de estos compitieron en la categoría 10k. ¿Cuál de las siguientes expresiones representa la cantidad de corredores extranjeros que compitieron en la categoría 10k?', to_jsonb(ARRAY['25 · 12 · 31 000','(25 + 12) · 31 000','0,25 · 0,12 · 31 000','(0,25 + 0,12) · 31 000']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una empresa de limpieza de automóviles realiza un cobro base de $20 000 por lavado y secado exterior del vehículo. Al agregar otros servicios extras, se cobra un adicional de $5000 por cada uno. La empresa ofrece un 15 % de descuento en el total a pagar si se realizan más de tres tipos de servicios extras. Si una persona realiza el lavado y secado exterior con cinco servicios extras, ¿cuánto es el total que debe pagar?', to_jsonb(ARRAY['$38 250','$41 250','$42 000','$42 750']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Para promocionar un negocio se contrata a un grupo de personas para que cada una pueda captar a un máximo de 20 clientes por día. Para calcular el pago diario, en pesos, que recibirá cada persona se utiliza el siguiente modelo: 2000 · C + 10 000, tal que C es la cantidad de clientes captados. Si una persona logró captar en un día 16 clientes, ¿qué porcentaje recibió del pago máximo diario?', to_jsonb(ARRAY['16 %','20 %','80 %','84 %']), 3, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Un Gúgol es un número muy grande cuyos dígitos son un 1 seguido por cien ceros. Por otra parte, un Gúgoplex es un número inmensamente más grande que el anterior cuyos dígitos son un 1 seguido por un Gúgol de ceros. ¿Cuál de los siguientes números equivale a un Gúgoplex?', to_jsonb(ARRAY['10^(10^100)','10^100 · 10^100','2 · 10^100','10^(1099)']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En un laboratorio, a partir de un estudio bajo ciertas condiciones, se determinó que un tipo de bacteria se duplica cada 4 minutos. Si en un instante se tenía una de estas bacterias, ¿cuánto tiempo transcurrió para tener 64 de esas bacterias?', to_jsonb(ARRAY['5 minutos','6 minutos','20 minutos','24 minutos']), 3, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Para organizar un torneo de ajedrez en dos grupos, se definió un sistema de clasificación por eliminación directa: un jugador se queda fuera del torneo al perder una partida. En la figura se muestra el esquema de las rondas hasta la final. Como la convocatoria al torneo fue exitosa, se decidió inscribir a más personas en el torneo, alcanzándose a completar los cupos para realizar una ronda más por grupo. ¿Cuántas personas participarán en el torneo de ajedrez?', to_jsonb(ARRAY['10','16','20','32']), 3, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId19.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Martina debe realizar un viaje por una calle recta y para esto revisa un mapa. En la figura adjunta se presenta el mapa y la distancia en el mapa entre los dos puntos que tiene que recorrer. Se sabe que 2 cm en el mapa equivalen a 200 m de distancia en la realidad. ¿Cuál es la distancia que debe recorrer Martina?', to_jsonb(ARRAY['400 m','1100 m','2200 m','4400 m']), 1, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId20.jpeg', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una persona preparará un postre de frutilla. La receta que tiene indica que por cada 500 gramos de frutilla deberá usar 200 gramos de azúcar. Para elaborar el postre utilizará 100 gramos más de frutilla de lo indicado en la receta. ¿Cuántos gramos de azúcar en total deberá utilizar la persona para mantener la proporción indicada en la receta?', to_jsonb(ARRAY['100','140','240','300']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En una empresa hay 4 trabajadores para cosechar uvas y estos logran llenar 2000 cajas en 20 días de trabajo, todos trabajando todos los días, al mismo ritmo y la misma cantidad de horas. En la empresa se realiza el siguiente procedimiento para calcular la cantidad de trabajadores necesarios para llenar 32 000 cajas en 10 días, bajo las mismas condiciones, cometiéndose un error. Paso 1: se calcula la cantidad de cajas que llenan diariamente los 4 trabajadores iniciales en conjunto como 2000/20, obteniéndose que llenan 100 cajas diarias. Paso 2: se calcula la cantidad de cajas que cada trabajador llena diariamente como 100 · 4, obteniéndose 400 cajas diarias por trabajador. Paso 3: se calcula la cantidad de cajas que se deben llenar diariamente para la nueva producción como 32 000/10, obteniéndose que deben llenar 3200 cajas diarias. Paso 4: se divide la cantidad de cajas diarias que deben llenar por la cantidad que cada trabajador llena diariamente como 3200/400, obteniéndose que necesitan 8 trabajadores. ¿En cuál de los pasos se cometió el error?', to_jsonb(ARRAY['En el Paso 1','En el Paso 2','En el Paso 3','En el Paso 4']), 1, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Josefa y Francisca asistieron al festival juvenil. La entrada a este evento tiene un precio de $20 000 por persona y quienes asistan pueden comprar chapitas para regalar a $500 cada una. Josefa gastó en total $30 000 por la entrada y por las chapitas que compró, y por cada 5 chapitas que compró Francisca, Josefa compró 4. ¿Cuánto gastó Francisca en chapitas en el festival?', to_jsonb(ARRAY['$12 500','$37 500','$42 500','$62 500']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En una empresa que se dedica a la mantención y reparación de calefont, trabajan Pedro, Joaquín, Rosario y Teresa, como técnicos. En una semana de trabajo se registra la cantidad de clientes atendidos por los técnicos, la cual dio un total de 79 clientes. En dicha semana Pedro atendió 18 clientes, Joaquín atendió 8 clientes más que Rosario y Teresa atendió 9 clientes más que Joaquín. ¿Cuántos clientes atendió Rosario en esa semana de trabajo?', to_jsonb(ARRAY['12','18','22','36']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Considera la siguiente oferta: un paquete de tallarines cuesta $800 y 1 kg de tomates cuesta $1800. Una persona tiene $10 000 para comprar un paquete de tallarines y la máxima cantidad de kilogramos de tomates posible. ¿Cuál de las siguientes inecuaciones permite determinar la máxima cantidad x de kilogramos de tomates que puede comprar la persona?', to_jsonb(ARRAY['10 000 − 800 ≥ 1800x','(10 000 − 800) / x ≥ 1800','10 000 + 800 ≥ 1800x','(10 000 + 800) / 1800 ≥ x']), 0, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId26.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Para la celebración de un evento familiar, una persona compró velas blancas y amarillas. En total, compró 14 velas y pagó $60 000. Si por cada vela blanca pagó $3000 y por cada vela amarilla pagó $6000, ¿cuántas velas blancas compró en total la persona?', to_jsonb(ARRAY['2','3','7','8']), 3, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Si (p − 3)² − 36 = 0, ¿cuál de los siguientes valores puede ser un valor de p?', to_jsonb(ARRAY['−15','−9','9','15']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una empresa contrata a una persona para que publique videos mostrando los beneficios de sus productos. La empresa le paga $150 000, más $100 000 por cada video publicado. ¿Cuál de las siguientes funciones modela el dinero que recibirá la persona tras publicar x videos para la empresa?', to_jsonb(ARRAY['f(x) = 150 000x + 100 000','g(x) = 100 000x + 150 000','h(x) = 100 000 · (x + 150 000)','k(x) = x · (100 000 + 150 000)']), 1, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la siguiente tabla se presenta la tarifa a cobrar por minuto para el uso de los estacionamientos de dos centros comerciales: Centro comercial R: $16 por minuto. Centro comercial Q: $30 por minuto. Para calcular el valor que se debe pagar por la estadía, desde el ingreso por la barrera de entrada hasta el pago en caja, se utiliza la expresión p · (t − 15), tal que p es la tarifa por minuto y t es la cantidad de minutos de la estadía (los primeros 15 minutos son gratis). Considerando una estadía de 55 minutos, ¿cuánto más caro es estacionar en el estacionamiento Q que en el estacionamiento R?', to_jsonb(ARRAY['$1200','$770','$640','$560']), 3, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la siguiente gráfica se representa la posición de un automóvil en distintos tiempos. ¿Cuánto tiempo estuvo detenido el automóvil?', to_jsonb(ARRAY['0,5 horas','1,5 horas','3,5 horas','4 horas']), 1, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId27.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Considera la función f definida por f(x) = 2x² − 7x + 1. ¿Cuál es el valor de f(−3)?', to_jsonb(ARRAY['−56','−38','40','58']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Un proyector de imágenes tiene una proporción de 9 : 16 entre la altura y el ancho de su proyección rectangular, siendo su altura el lado menor. Al situar el proyector a cierta distancia de la pared, la longitud de la diagonal del rectángulo de proyección será de 100 pulgadas. Para calcular la altura de este rectángulo de proyección, se utiliza el siguiente modelo: (9x)² + (16x)² = 100². ¿Qué representa 16x en el modelo?', to_jsonb(ARRAY['El factor de proporcionalidad','El ancho del rectángulo de proyección','La altura del rectángulo de proyección','La distancia desde el proyector hasta la pared']), 1, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId33.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la parte superior de un poste de 3 metros de altura perpendicular al suelo, se atan dos cuerdas de manera tensa, quedando de 4 metros cada una. Para determinar la distancia x con respecto al poste, se realiza el siguiente procedimiento, cometiéndose un error. Paso 1: para calcular la longitud x se decide utilizar el teorema de Pitágoras, obteniéndose x² + 3² = 4². Paso 2: se calculan las potencias en la ecuación anterior, obteniéndose x² + 9 = 16. Paso 3: se despeja x, obteniéndose x = √(16 + 9). Paso 4: se calcula la raíz cuadrada del paso anterior, obteniéndose la distancia de 5 metros. ¿En cuál de los pasos se cometió el error?', to_jsonb(ARRAY['En el Paso 1','En el Paso 2','En el Paso 3','En el Paso 4']), 2, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId34.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Las diagonales de un rombo miden 24 cm y 30 cm. ¿Cuál es su área?', to_jsonb(ARRAY['180 cm2','360 cm2','720 cm2','1440 cm2']), 1, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una empresa que vende cajas de cereales decide ofrecer una oferta que implica un nuevo diseño de caja, un 10 % más alta que el diseño original. ¿Cuál es el volumen de la caja con oferta si sus medidas originales eran de 20 cm de largo, 5 cm de fondo y 30 cm de alto?', to_jsonb(ARRAY['300 cm3','3300 cm3','3993 cm3','4000 cm3']), 1, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId35.jpeg', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Un estanque de agua tiene forma de prisma recto de base rectangular, cuya base mide 4 m de ancho y 3 m de largo. Este se debe llenar hasta 2 m de altura con agua proveniente de un ducto. Para calcular el caudal del agua que sale de un ducto, se puede utilizar la expresión V/t, tal que V corresponde al volumen de agua que sale del ducto durante t unidades de tiempo. ¿Cuál de las siguientes expresiones corresponde al caudal de agua, en m3/h, para que el estanque se llene hasta 2 m de altura en 10 horas?', to_jsonb(ARRAY['(4 · 3 · 2) / 10','(4 + 3 + 2) / 10','2(4 + 3) / 10','2(4 · 3 + 2 · 4 + 2 · 3) / 10']), 0, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En un plano cartesiano se proyecta la sombra de la cara de un gato. ¿Cuál de los siguientes puntos pertenece a la sombra de la cara del gato?', to_jsonb(ARRAY['(2, 4)','(5, 5)','(7, −4)','(−1, 3)']), 3, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId37.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la figura adjunta se representa un cuadrilátero cuyas medidas están en centímetros. ¿Cuál de las siguientes expresiones corresponde al perímetro del cuadrilátero?', to_jsonb(ARRAY['22 cm','(√6 + 15) cm','20 cm','(√29 + 15) cm']), 3, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId59.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la siguiente tabla se presenta el tiempo que las personas han trabajado en un colegio: 1 año (2 personas), 2 años (4), 3 años (5), 4 años (4), 5 años (2), 6 años (6), 7 años (2), 8 años (5), 9 años (3), 10 años (2). Si se entrega una bonificación salarial a aquellas personas que lleven como mínimo 6 años trabajando en el colegio, ¿cuántas personas recibirán la bonificación salarial?', to_jsonb(ARRAY['12','17','18','23']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En el siguiente gráfico se presenta la producción mensual de huevos de consumo en Chile desde febrero de 2024 a febrero de 2025. ¿Cuál de las siguientes afirmaciones interpreta de mejor manera la evolución de la producción mensual a lo largo del periodo?', to_jsonb(ARRAY['Hasta agosto la producción aumentó mes a mes.','En enero de 2024 no hubo producción.','En junio hubo la menor producción.','En agosto hubo la mayor producción.']), 3, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId60.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una municipalidad desea implementar un plan de vacunación y esterilización de mascotas, para lo cual realiza una encuesta sobre la cantidad de mascotas que hay en cierto sector: 0 mascotas (12 familias), 1 (10), 2 (15), 3 (6), 4 (5), 5 o más (2). Esta municipalidad dará un beneficio a las familias que tengan 3 o más mascotas, que consiste en vacunación o esterilización gratis. ¿Cuál de las siguientes expresiones representa el porcentaje de familias beneficiadas?', to_jsonb(ARRAY['(7/50) · 100 %','(13/50) · 100 %','(37/50) · 100 %','(43/50) · 100 %']), 1, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En el siguiente gráfico se presentan los resultados de una encuesta realizada el 2016 a un grupo de personas estadounidenses y a un grupo de nutricionistas sobre qué alimentos consideraban saludables. ¿Para qué alimento existe la mayor diferencia entre los porcentajes según lo que consideran saludable el grupo de nutricionistas versus el grupo de estadounidenses encuestados?', to_jsonb(ARRAY['Helado','Quínoa','Manzana','Barra de cereal']), 3, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId61.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'El examen médico de tolerancia a la glucosa consiste en medir la respuesta del cuerpo a la glucosa. Se inicia midiendo la concentración de la glucosa basal y luego se ingiere un líquido con una determinada concentración de glucosa para monitorear su concentración en el cuerpo al transcurrir las horas. En el siguiente gráfico se representa la concentración de glucosa en el cuerpo de un paciente al realizarse este examen. ¿Cuál de las siguientes afirmaciones se puede deducir del gráfico?', to_jsonb(ARRAY['El paciente ingiere la glucosa aproximadamente una hora después de iniciar el examen.','La concentración de glucosa se estabiliza en su nivel basal luego de aproximadamente 4 horas de ingerir glucosa.','La concentración de glucosa basal del paciente es de 110 mg/dL, aproximadamente.','El punto más alto de la concentración de glucosa sucede 3 horas después de ingerir la glucosa.']), 1, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId62.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En los siguientes pictogramas se representa la cantidad de personas que hay en cinco grupos, tal que cada ícono corresponde a una persona. ¿En cuál de los pictogramas hay un mayor promedio de personas por grupo?', to_jsonb(ARRAY['En el pictograma 1','En el pictograma 2','En el pictograma 3','En el pictograma 4']), 2, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId64.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'El promedio de edad de un grupo A de personas es 30 años, mientras que el promedio de edad de un grupo B de personas es 40 años. Si se quiere cambiar solo a una persona de grupo, ¿en cuál de los siguientes casos el promedio aumentará en ambos grupos?', to_jsonb(ARRAY['Que se cambie una persona de 45 años del grupo B al grupo A.','Que se cambie una persona de 35 años del grupo B al grupo A.','Que se cambie una persona de 45 años del grupo A al grupo B.','Que se cambie una persona de 30 años del grupo A al grupo B.']), 1, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En la siguiente tabla se presenta el gasto diario en almuerzo de una persona durante una semana: Lunes $3200, Martes $5300, Miércoles $7200, Jueves $2500, Viernes $11 400, Sábado $12 000, Domingo $6000. ¿Cuánto dinero gastó en promedio diariamente en almuerzo esa semana?', to_jsonb(ARRAY['$2500','$6000','$6800','$9520']), 2, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En el siguiente gráfico se presenta el promedio de las puntuaciones que ha recibido un hotel por parte de sus huéspedes con respecto a seis categorías. Si todas las personas contestaron todas las categorías, ¿cuál es el promedio general de puntuación del hotel considerando estas seis categorías?', to_jsonb(ARRAY['4,7 puntos','4,8 puntos','4,9 puntos','5 puntos']), 1, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId65.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'En el siguiente diagrama de cajón se presenta el tiempo que tardó un grupo de personas en completar un circuito deportivo. ¿Qué representa el 16 en el diagrama de cajón?', to_jsonb(ARRAY['Que al menos un 75 % de las personas terminó el circuito en 16 minutos o menos.','Que un 16 % de las personas terminó el circuito en a lo más 16 minutos.','Que la dieciseisava persona que terminó el circuito demoró 16 minutos.','Que la cuarta persona que terminó el circuito demoró 16 minutos.']), 0, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId66.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Para una tarea de Estadística, una estudiante tiene que representar un conjunto de datos a través de un diagrama de cajón. Los datos corresponden a la cantidad de anotaciones positivas que tuvieron los amigos de esta estudiante el semestre anterior: 4, 0, 0, 2, 3, 3, 1, 0, 3. Para construir el diagrama de cajón, ella realiza los siguientes pasos, cometiendo un error. Paso 1: ordena los datos de menor a mayor y determina que el dato central es 2. Paso 2: identifica los valores mínimo y máximo, obteniendo 0 y 4 respectivamente. Paso 3: determina el primer cuartil como 1, ya que se encuentra entre 0 y 2, y el tercer cuartil como 3, ya que se encuentra entre 2 y 4. Paso 4: construye el diagrama de cajón. ¿En cuál de los pasos la estudiante cometió el error?', to_jsonb(ARRAY['En el Paso 1','En el Paso 2','En el Paso 3','En el Paso 4']), 2, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId67.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'Una ruleta está dividida en nueve partes de igual área. Un juego consiste en realizar 3 giros de la ruleta, pero si en algunos de esos giros se obtiene un fantasma, se termina el juego y no se puede seguir girando, y el premio es la suma de lo obtenido en cada giro. Por cada estrella se ganan $50 000 y por cada diamante se ganan $100 000. La probabilidad de ganar exactamente $100 000 en un juego se calcula con una expresión que suma dos términos. ¿Qué representa uno de esos términos?', to_jsonb(ARRAY['La probabilidad de sacar un diamante en el primer lanzamiento y una estrella en el segundo.','La probabilidad de sacar un diamante en el primer lanzamiento y un fantasma en el segundo.','La probabilidad de sacar una estrella en el primer lanzamiento, una estrella en el segundo y un fantasma en el tercero.','La probabilidad de sacar dos estrellas en los dos primeros lanzamientos y un diamante en el tercero.']), 2, 'media', true, 'https://mkrqjohtkgjommwvtorp.supabase.co/storage/v1/object/public/preguntas-imagenes/38739805-0d32-4226-abaf-8caf023e9c24/paesm1-rId69.png', '04952ed1-21d3-46cc-a262-92e12644e0b3'),
('38739805-0d32-4226-abaf-8caf023e9c24', 'De acuerdo al estudio "Profundización de Ocupaciones 2024" de la Subsecretaría del Trabajo, la cantidad de guías de turismo registrados en Chile es 3621 y en la Región de Valparaíso es 441. Las comunas de la Región de Valparaíso con más guías de turismo son: Rapa Nui (172), Valparaíso (64), Viña del Mar (51). Si se escoge al azar a un guía de turismo de la Región de Valparaíso, ¿cuál de las siguientes expresiones representa la probabilidad de que esté registrado en la comuna de Valparaíso o en la de Viña del Mar?', to_jsonb(ARRAY['64 / 441','(64 + 51) / 441','(64 + 51) / 3621','64 / 3621']), 1, 'media', true, null, '04952ed1-21d3-46cc-a262-92e12644e0b3');
